-- VINEET FURNISHINGS ERP - clean schema using BIGINT IDs consistently
create table if not exists public.parties (id bigint generated by default as identity primary key,name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.beams (id bigint generated by default as identity primary key,name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.shades (id bigint generated by default as identity primary key,name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.sizes (id bigint generated by default as identity primary key,name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.designs (id bigint generated by default as identity primary key,name text not null unique,beam_id bigint references public.beams(id) on delete restrict,shade_id bigint references public.shades(id) on delete restrict,size_id bigint references public.sizes(id) on delete restrict,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.design_threads (id bigint generated by default as identity primary key,design_id bigint not null references public.designs(id) on delete cascade,thread_name text not null,sort_order integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.loom_programs (id bigint generated by default as identity primary key,loom_number integer not null check(loom_number between 1 and 52),production_date date not null,status text not null default 'draft' check(status in('draft','active','completed','cancelled')),operator_name text,created_at timestamptz not null default now());
create table if not exists public.loom_program_rows (id bigint generated by default as identity primary key,program_id bigint not null references public.loom_programs(id) on delete cascade,party_id bigint not null references public.parties(id) on delete restrict,po_number text not null,po_date date,design_id bigint not null references public.designs(id) on delete restrict,beam_id bigint references public.beams(id) on delete restrict,shade_id bigint references public.shades(id) on delete restrict,size_id bigint references public.sizes(id) on delete restrict,pick numeric(12,2),planned_meters numeric(14,2) not null default 0,planned_articles integer not null default 0,remarks text,created_at timestamptz not null default now());
create table if not exists public.production_entries (id bigint generated by default as identity primary key,program_row_id bigint not null references public.loom_program_rows(id) on delete restrict,production_date date not null,actual_meters numeric(14,2) not null default 0,actual_articles integer not null default 0,rejected_articles integer not null default 0,downtime_minutes integer not null default 0,remarks text,created_at timestamptz not null default now());
create index if not exists idx_designs_name on public.designs(name);
create index if not exists idx_programs_loom_date on public.loom_programs(loom_number,production_date);
create index if not exists idx_rows_party on public.loom_program_rows(party_id);
create index if not exists idx_rows_design on public.loom_program_rows(design_id);
